-- Rana Medical Hospital ERP — PostgreSQL 15+ starter schema
-- Apply only after DBA review. Contains no real patient records.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, description text NOT NULL);
CREATE TABLE role_permissions(role_id uuid REFERENCES roles(id) ON DELETE CASCADE, permission_id uuid REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_id uuid NOT NULL REFERENCES roles(id), employee_id uuid, email citext UNIQUE, phone text, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, last_login_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_no text UNIQUE NOT NULL, full_name text NOT NULL, phone text, email citext, designation text, department_id uuid REFERENCES departments(id), hire_date date, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
ALTER TABLE users ADD CONSTRAINT users_employee_fk FOREIGN KEY(employee_id) REFERENCES employees(id);
CREATE TABLE doctors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid REFERENCES employees(id), display_name text NOT NULL, specialty text NOT NULL, qualifications text, pmdc_registration text, pmdc_verified_at timestamptz, experience_years smallint CHECK(experience_years>=0), consultation_fee_paisa bigint NOT NULL DEFAULT 0 CHECK(consultation_fee_paisa>=0), opd_days text[] NOT NULL DEFAULT '{}', opd_start time, opd_end time, public_visible boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX doctors_specialty_idx ON doctors(specialty) WHERE deleted_at IS NULL;
CREATE TABLE patients(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_no text UNIQUE NOT NULL, full_name text NOT NULL, date_of_birth date, sex text CHECK(sex IN ('female','male','other','unknown')), phone text, email citext, address text, emergency_contact_name text, emergency_contact_phone text, consent_recorded_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX patients_phone_idx ON patients(phone) WHERE deleted_at IS NULL;
CREATE TABLE patient_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), storage_key text NOT NULL, document_type text NOT NULL, uploaded_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE patient_allergies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), substance text NOT NULL, reaction text, severity text, recorded_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE patient_vitals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), visit_id uuid, recorded_by uuid NOT NULL REFERENCES users(id), systolic smallint, diastolic smallint, temperature_c numeric(4,1), pulse_bpm smallint, glucose_mmol numeric(5,2), weight_kg numeric(5,2), height_cm numeric(5,2), oxygen_saturation numeric(5,2), recorded_at timestamptz NOT NULL DEFAULT now(), CHECK(oxygen_saturation BETWEEN 0 AND 100));
CREATE INDEX patient_vitals_patient_time_idx ON patient_vitals(patient_id,recorded_at DESC);
CREATE TABLE appointments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference text UNIQUE NOT NULL, patient_id uuid REFERENCES patients(id), patient_name text NOT NULL, patient_phone text NOT NULL, department_id uuid REFERENCES departments(id), doctor_id uuid REFERENCES doctors(id), requested_date date NOT NULL, requested_time time NOT NULL, status text NOT NULL DEFAULT 'booked' CHECK(status IN ('booked','confirmed','waiting','with_doctor','completed','cancelled','no_show')), source text NOT NULL DEFAULT 'web', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE INDEX appointments_queue_idx ON appointments(requested_date,department_id,status);
CREATE TABLE tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), appointment_id uuid REFERENCES appointments(id), patient_id uuid REFERENCES patients(id), token_no text NOT NULL, service_date date NOT NULL, status text NOT NULL DEFAULT 'waiting', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(service_date,token_no));
CREATE TABLE opd_visits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), appointment_id uuid REFERENCES appointments(id), doctor_id uuid NOT NULL REFERENCES doctors(id), department_id uuid REFERENCES departments(id), token_id uuid REFERENCES tokens(id), visited_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'open', created_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE patient_vitals ADD CONSTRAINT patient_vitals_visit_fk FOREIGN KEY(visit_id) REFERENCES opd_visits(id);
CREATE TABLE diagnoses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL REFERENCES opd_visits(id), code text, description text NOT NULL, type text NOT NULL DEFAULT 'working', created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE clinical_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL REFERENCES opd_visits(id), note_type text NOT NULL, body text NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), amended_at timestamptz);
CREATE TABLE prescriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), visit_id uuid NOT NULL REFERENCES opd_visits(id), patient_id uuid NOT NULL REFERENCES patients(id), prescriber_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now(), signed_at timestamptz);
CREATE TABLE medicines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), generic_name text NOT NULL, brand_name text, strength text, dosage_form text, category text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE prescription_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), prescription_id uuid NOT NULL REFERENCES prescriptions(id), medicine_id uuid REFERENCES medicines(id), medicine_text text NOT NULL, strength text, dosage text, frequency text, duration text, instructions text, quantity numeric(10,2) CHECK(quantity>=0));
CREATE TABLE suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, phone text, email citext, address text, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE medicine_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), medicine_id uuid NOT NULL REFERENCES medicines(id), batch_no text NOT NULL, expiry_date date NOT NULL, purchase_price_paisa bigint NOT NULL CHECK(purchase_price_paisa>=0), sale_price_paisa bigint NOT NULL CHECK(sale_price_paisa>=0), stock_qty numeric(12,3) NOT NULL DEFAULT 0 CHECK(stock_qty>=0), supplier_id uuid REFERENCES suppliers(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(medicine_id,batch_no));
CREATE INDEX medicine_batch_expiry_idx ON medicine_batches(expiry_date);
CREATE TABLE pharmacy_sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid, prescription_id uuid REFERENCES prescriptions(id), cashier_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'draft', subtotal_paisa bigint NOT NULL DEFAULT 0, discount_paisa bigint NOT NULL DEFAULT 0, total_paisa bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pharmacy_sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sale_id uuid NOT NULL REFERENCES pharmacy_sales(id), batch_id uuid NOT NULL REFERENCES medicine_batches(id), quantity numeric(12,3) NOT NULL CHECK(quantity>0), unit_price_paisa bigint NOT NULL CHECK(unit_price_paisa>=0));
CREATE TABLE purchase_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), supplier_id uuid NOT NULL REFERENCES suppliers(id), order_no text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'draft', ordered_at timestamptz NOT NULL DEFAULT now(), received_at timestamptz, created_by uuid REFERENCES users(id));
CREATE TABLE purchase_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), purchase_order_id uuid NOT NULL REFERENCES purchase_orders(id), medicine_id uuid NOT NULL REFERENCES medicines(id), batch_no text, expiry_date date, quantity numeric(12,3) NOT NULL CHECK(quantity>0), unit_cost_paisa bigint NOT NULL CHECK(unit_cost_paisa>=0));
CREATE TABLE lab_tests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, description text, price_paisa bigint NOT NULL CHECK(price_paisa>=0), turnaround_hours integer, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE lab_parameters(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), test_id uuid NOT NULL REFERENCES lab_tests(id), name text NOT NULL, unit text, reference_min numeric, reference_max numeric, sex text, age_min_days integer, age_max_days integer, sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE lab_orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), visit_id uuid REFERENCES opd_visits(id), ordered_by uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'ordered', verification_mobile_hash text, ordered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lab_order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES lab_orders(id), test_id uuid NOT NULL REFERENCES lab_tests(id), status text NOT NULL DEFAULT 'ordered');
CREATE TABLE lab_samples(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_item_id uuid NOT NULL REFERENCES lab_order_items(id), accession_no text UNIQUE NOT NULL, sample_type text, collected_by uuid REFERENCES users(id), collected_at timestamptz, received_at timestamptz, status text NOT NULL DEFAULT 'pending');
CREATE TABLE lab_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_item_id uuid NOT NULL REFERENCES lab_order_items(id), parameter_id uuid REFERENCES lab_parameters(id), value_text text NOT NULL, numeric_value numeric, unit text, flag text CHECK(flag IN ('low','normal','high','critical','unclassified')), entered_by uuid NOT NULL REFERENCES users(id), entered_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE lab_reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES lab_orders(id), report_no text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','entered','verified','published','recalled')), verified_by uuid REFERENCES users(id), verified_at timestamptz, published_at timestamptz, public_verification_hash text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wards(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text UNIQUE NOT NULL, ward_type text NOT NULL);
CREATE TABLE rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ward_id uuid NOT NULL REFERENCES wards(id), room_no text NOT NULL, daily_rate_paisa bigint NOT NULL DEFAULT 0 CHECK(daily_rate_paisa>=0), UNIQUE(ward_id,room_no));
CREATE TABLE beds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), room_id uuid NOT NULL REFERENCES rooms(id), bed_no text NOT NULL, status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','occupied','maintenance')), UNIQUE(room_id,bed_no));
CREATE TABLE admissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), admission_no text UNIQUE NOT NULL, attending_doctor_id uuid REFERENCES doctors(id), admitted_at timestamptz NOT NULL DEFAULT now(), discharged_at timestamptz, status text NOT NULL DEFAULT 'active', created_by uuid NOT NULL REFERENCES users(id));
CREATE TABLE bed_stays(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid NOT NULL REFERENCES admissions(id), bed_id uuid NOT NULL REFERENCES beds(id), start_at timestamptz NOT NULL DEFAULT now(), end_at timestamptz, daily_rate_paisa bigint NOT NULL CHECK(daily_rate_paisa>=0));
CREATE UNIQUE INDEX one_active_bed_per_admission ON bed_stays(admission_id) WHERE end_at IS NULL;
CREATE TABLE nursing_notes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid NOT NULL REFERENCES admissions(id), author_id uuid NOT NULL REFERENCES users(id), note text NOT NULL, shift text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE medication_administration(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid NOT NULL REFERENCES admissions(id), prescription_item_id uuid REFERENCES prescription_items(id), administered_by uuid NOT NULL REFERENCES users(id), administered_at timestamptz NOT NULL, status text NOT NULL, note text);
CREATE TABLE doctor_rounds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admission_id uuid NOT NULL REFERENCES admissions(id), doctor_id uuid NOT NULL REFERENCES doctors(id), note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE surgery_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES patients(id), admission_id uuid REFERENCES admissions(id), procedure_name text NOT NULL, surgeon_id uuid NOT NULL REFERENCES doctors(id), anaesthesia_details text, scheduled_start timestamptz, status text NOT NULL DEFAULT 'planned', post_op_notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_no text UNIQUE NOT NULL, patient_id uuid REFERENCES patients(id), visit_id uuid REFERENCES opd_visits(id), admission_id uuid REFERENCES admissions(id), status text NOT NULL DEFAULT 'open', currency char(3) NOT NULL DEFAULT 'PKR', subtotal_paisa bigint NOT NULL DEFAULT 0, discount_paisa bigint NOT NULL DEFAULT 0, total_paisa bigint NOT NULL DEFAULT 0, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK(total_paisa>=0));
CREATE TABLE invoice_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), source_type text NOT NULL, source_id uuid, description text NOT NULL, quantity numeric(12,3) NOT NULL DEFAULT 1, unit_price_paisa bigint NOT NULL CHECK(unit_price_paisa>=0), amount_paisa bigint NOT NULL CHECK(amount_paisa>=0));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES invoices(id), receipt_no text UNIQUE NOT NULL, amount_paisa bigint NOT NULL CHECK(amount_paisa>0), method text NOT NULL, received_by uuid NOT NULL REFERENCES users(id), reference text, received_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX payments_invoice_idx ON payments(invoice_id,received_at);
CREATE TABLE expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), expense_no text UNIQUE NOT NULL, category text NOT NULL, description text NOT NULL, amount_paisa bigint NOT NULL CHECK(amount_paisa>0), vendor_id uuid REFERENCES suppliers(id), paid_at timestamptz, payment_method text, approved_by uuid REFERENCES users(id), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commission_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), doctor_id uuid REFERENCES doctors(id), department_id uuid REFERENCES departments(id), service_type text NOT NULL, rate_basis_points integer NOT NULL CHECK(rate_basis_points BETWEEN 0 AND 10000), effective_from date NOT NULL, effective_to date, approved_by uuid REFERENCES users(id));
CREATE TABLE doctor_commissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), doctor_id uuid NOT NULL REFERENCES doctors(id), invoice_item_id uuid NOT NULL REFERENCES invoice_items(id), amount_paisa bigint NOT NULL CHECK(amount_paisa>=0), status text NOT NULL DEFAULT 'accrued', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES employees(id), work_date date NOT NULL, clock_in timestamptz, clock_out timestamptz, status text NOT NULL, UNIQUE(employee_id,work_date));
CREATE TABLE leave_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES employees(id), starts_on date NOT NULL, ends_on date NOT NULL, reason text, status text NOT NULL DEFAULT 'pending', approved_by uuid REFERENCES users(id));
CREATE TABLE payroll_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_start date NOT NULL, period_end date NOT NULL, status text NOT NULL DEFAULT 'draft', approved_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(period_start,period_end));
CREATE TABLE payroll_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payroll_run_id uuid NOT NULL REFERENCES payroll_runs(id), employee_id uuid NOT NULL REFERENCES employees(id), gross_paisa bigint NOT NULL CHECK(gross_paisa>=0), deductions_paisa bigint NOT NULL DEFAULT 0, net_paisa bigint NOT NULL CHECK(net_paisa>=0), paid_at timestamptz, UNIQUE(payroll_run_id,employee_id));
CREATE TABLE website_services(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text, sort_order integer NOT NULL DEFAULT 0, published boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE packages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, description text, price_paisa bigint NOT NULL CHECK(price_paisa>=0), inclusions jsonb NOT NULL DEFAULT '[]', published boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE blog_posts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, title text NOT NULL, body text NOT NULL, author_id uuid REFERENCES users(id), published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE testimonials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), display_name text NOT NULL, department text, rating smallint CHECK(rating BETWEEN 1 AND 5), body text NOT NULL, consent_verified_at timestamptz, published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, contact text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'new', assigned_to uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), type text NOT NULL, payload jsonb NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text, entity_id uuid, request_id text, ip inet, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_logs_created_idx ON audit_logs(created_at DESC);
CREATE TABLE settings(key text PRIMARY KEY, value jsonb NOT NULL, updated_by uuid REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ambulances(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), vehicle_no text UNIQUE NOT NULL, driver_name text, driver_phone text, status text NOT NULL DEFAULT 'unknown', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ambulance_dispatches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ambulance_id uuid REFERENCES ambulances(id), patient_id uuid REFERENCES patients(id), caller_phone text, pickup_location text, destination text, dispatched_at timestamptz, returned_at timestamptz, status text NOT NULL DEFAULT 'requested', created_by uuid REFERENCES users(id));
COMMIT;
-- Financial posting, dispensing, bed assignment and report publication MUST be
-- implemented as audited DB transactions with role policies and operational review.
